parameters.jsCode:
// Récupère les données brutes
const rawAlert = $('Extract Alert').first()?.json?.body || {};
const mispRaw = $('HTTP Request misp').first()?.json || {};
const openctiRaw = $('HTTP Request opencti').first()?.json || {};

let mispData = null;
if (mispRaw.Event) {
  mispData = { found: true, event: mispRaw.Event, attributes: mispRaw.Event.Attribute || [] };
} else if (mispRaw.response?.Event) {
  mispData = { found: true, event: mispRaw.response.Event, attributes: mispRaw.response.Event.Attribute || [] };
} else {
  mispData = { found: false, event: null, attributes: [] };
}

let openctiData = null;
if (openctiRaw.data?.indicators?.edges) {
  const edges = openctiRaw.data.indicators.edges;
  openctiData = { found: edges.length > 0, full_response: openctiRaw.data, indicators: edges.map(e => e.node).filter(Boolean) };
} else {
  openctiData = { found: false, full_response: openctiRaw, indicators: [] };
}

const wazuhAlert = {
  id: rawAlert.rule?.id ?? rawAlert.id,
  correlation_id: rawAlert.correlation_id,
  timestamp: rawAlert.timestamp,
  level: rawAlert.rule?.level,
  description: rawAlert.rule?.description ?? rawAlert.full_log,
  src_ip: rawAlert.data?.srcip,
  dst_ip: rawAlert.data?.dstip,
  agent: rawAlert.agent,
  full_raw: rawAlert
};

const totalMatches = (mispData.attributes?.length || 0) + (openctiData.indicators?.length || 0);
let preliminary_verdict = totalMatches > 0 ? "intel_found" : "no_intel";

return [{
  json: {
    wazuh_alert: wazuhAlert,
    threat_intelligence: { misp: mispData, opencti: openctiData },
    correlation_summary: {
      total_matches: totalMatches,
      preliminary_verdict,
      misp_attributes_count: mispData.attributes?.length || 0,
      opencti_indicators_count: openctiData.indicators?.length || 0
    },
    analysis_request: {
      task: "Analyze this security alert and determine if it's a TRUE POSITIVE or FALSE POSITIVE",
      context: { source: "Wazuh SIEM alert enriched with MISP and OpenCTI threat intelligence", goal: "Provide actionable security analysis" }
    }
  }
}];

const original = $('Code').first().json;
const llamaResponse = $input.first().json;

let ai = llamaResponse.response ?? llamaResponse;

if (typeof ai === 'string') {
  try {
    ai = JSON.parse(ai.replace(/```json|```/g, '').trim());
  } catch (e) {
    ai = { error: 'parse_failed', raw: ai };
  }
}
if (Array.isArray(ai)) ai = ai[0];

return [
  {
    json: {
      correlation_id: original.wazuh_alert?.correlation_id,
      alert: original.wazuh_alert ?? original,
      threat_intel: original.threat_intelligence ?? null,
      correlation: original.correlation_summary ?? null,
      ai_analysis: ai
    }
  }
];

const raw = $input.first().json;
let payload = raw;

if (raw.body && raw.body.rule) {
  payload = raw.body;
} else if (raw.rule) {
  payload = raw;
} else if (raw.message && raw.message.rule) {
  payload = raw.message;
} else if (typeof raw.message === 'string') {
  try { payload = JSON.parse(raw.message); } catch(e) {}
} else if (raw.content && typeof raw.content === 'string') {
  try {
    const parsedContent = JSON.parse(raw.content);
    payload = parsedContent.body || parsedContent;
  } catch(e) {}
}

// Correlation ID pour tracer l'alerte à travers le fast-path ET le slow-path
payload.correlation_id = payload.correlation_id || (Date.now() + '-' + Math.random().toString(36).substring(2, 10));


return [{ json: { body: payload } }];

const data = $input.first().json;
const aiAnalysis = data.ai_analysis || {};
const automatedAction = aiAnalysis.automated_action || {};

const IP_BLOCK_TYPES = ['firewall-drop', 'BLOCK_IP', 'block-ip', 'BLOCK'];
const PORT_BLOCK_TYPES = ['BLOCK_PORT', 'block-port', 'FIREWALL_PORT_DROP'];
const actions = [];

// Compat rétroactive : si l'IA renvoie encore l'ancien format (action_type unique),
// on le transforme en tableau à un seul élément.
let rawActions = automatedAction.actions;
if (!Array.isArray(rawActions) && automatedAction.action_type) {
  rawActions = [{ action_type: automatedAction.action_type, target: automatedAction.target, port: automatedAction.port, scope: automatedAction.scope }];
}
rawActions = rawActions || [];

if (automatedAction.execute === true) {
  for (const act of rawActions) {
    const type = act.action_type;
    const target = act.target;

    if (IP_BLOCK_TYPES.includes(type)) {
      actions.push({ type: 'block_ip', command: 'block-ip600', target, source: 'Wazuh-AI-Agent' });
    }

    if (PORT_BLOCK_TYPES.includes(type)) {
      const scope = act.scope === 'GLOBAL' ? 'GLOBAL' : 'SOURCE_IP';
      actions.push({
        type: 'block_port',
        command: 'block-port600',
        target: scope === 'GLOBAL' ? 'ANY' : target,
        port: act.port,
        scope,
        source: 'Wazuh-AI-Agent'
      });
    }

    if (type === 'CREATE_HIVE_CASE' || IP_BLOCK_TYPES.includes(type) || PORT_BLOCK_TYPES.includes(type)) {
      actions.push({
        type: 'hive_case',
        title: `Alerte Wazuh: ${aiAnalysis.analysis_context || 'Suspicious Activity'}`,
        description: aiAnalysis.reasoning || 'Analyse IA requise',
        severity: (aiAnalysis.confidence_score || 0) > 80 ? 3 : 2,
        source: 'Wazuh-AI-Agent',
        target
      });
    }

    if (type === 'RUN_CORTEX_ANALYZER') {
      actions.push({ type: 'cortex_analyzer', analyzerId: 'ipinfo', dataType: 'ip', data: target, cortexId: 'default' });
    }
  }
}

return [{ json: { ...data, actions_to_execute: actions, agent_decision: automatedAction } }];

const alert = $json.body?.alert ?? {};

// Centralise ici les noms de commandes AR tels que définis dans ar.conf
// Si le timeout change dans ossec.conf, on ne modifie QUE cette ligne.
const AR_BLOCK_TIMEOUT = 600;
const AR_UNBLOCK_TIMEOUT = 0;

const agentId = alert.agent?.id;
if (!agentId) {
  throw new Error('agent.id manquant dans le payload alert — impossible de cibler un agent Wazuh');
}

return {
  json: {
    correlation_id: $json.body?.correlation_id ?? 'unknown',
    action_type: 'BLOCK_IP',
    agent_id: agentId,
    target: alert.data?.srcip ?? 'unknown',
    rule_id: String(alert.rule?.id ?? 'unknown'),
    rule_level: Number(alert.rule?.level ?? 0),
    reason: 'high severity rule match',
    ar_block_command: `block-ip${AR_BLOCK_TIMEOUT}`,
    ar_unblock_command: `unblock-ip${AR_UNBLOCK_TIMEOUT}`
  }
};

