const combineResult = $('Combine Result').first().json;
const items = $input.all();

const ai = combineResult.ai_analysis || {};
const texte = `${ai.verdict || ''} ${ai.classification || ''} ${ai.recommendation || ''}`.toLowerCase();
const isFalsePositive =
  texte.includes('false_positive') ||
  texte.includes('false positive') ||
  texte.includes('faux positif') ||
  texte.includes('Faux positif') ||
  texte.includes('legitimate');

// Ne garder que les lignes reellement en attente (BLOCK_IP et/ou BLOCK_PORT)
const pendingRows = items.map(i => i.json).filter(row => row && row.has_pending_action === true);

if (pendingRows.length === 0) {
  // Aucune action preemptive (ni IP ni Port) prise pour ce correlation_id :
  // on laisse l'agent IA decider d'une action fraiche (voir Routeur Agent IA)
  return [{
    json: {
      ...combineResult,
      has_pending_action: false,
      pending_action: null,
      reconciliation_decision: 'no_preemptive_action'
    }
  }];
}

// 1 ou 2 lignes en attente : une decision independante par ligne
// (ex: confirmer le blocage IP, mais rollback le blocage de port, ou l'inverse)
return pendingRows.map(row => ({
  json: {
    ...combineResult,
    has_pending_action: true,
    pending_action: row,
    reconciliation_decision: isFalsePositive ? 'rollback' : 'confirm'
  }
}));

