// Prend le 1er élément si c'est un tableau, sinon l'objet tel quel
let slowItem = $input.first().json;
if (Array.isArray(slowItem)) slowItem = slowItem[0] || {};
return [{ json: slowItem }];

const alert = $json.body?.alert ?? {};

// Liste centralisee des ports consideres critiques.
// A ajuster selon le contexte (services exposes, criticite metier).
const CRITICAL_PORTS = [21, 22, 23, 135, 139, 445, 1433, 1521, 3306, 3389,
                         5432, 5900, 5985, 5986, 6379, 9200, 27017];

const dstPort = Number(
  alert.data?.dstport ?? alert.data?.dest_port ?? alert.data?.port ?? 0
);
const ruleLevel = Number(alert.rule?.level ?? 0);
const isCriticalPort = CRITICAL_PORTS.includes(dstPort);

return [{
  json: {
    ...$json,
    dst_port: dstPort,
    is_critical_port: isCriticalPort,
    port_block_eligible: ruleLevel >= 12 && isCriticalPort
  }
}];

const alert = $json.body?.alert ?? {};

// Meme principe que Build Preemptive Action, pour le blocage de port.
const AR_BLOCK_TIMEOUT = 600;
const AR_UNBLOCK_TIMEOUT = 0;

const agentId = alert.agent?.id;
if (!agentId) {
  throw new Error('agent.id manquant dans le payload alert - impossible de cibler un agent Wazuh');
}

const srcIp = alert.data?.srcip ?? 'unknown';
const dstPort = $json.dst_port ?? (alert.data?.dstport ?? 'unknown');

return {
  json: {
    correlation_id: $json.body?.correlation_id ?? 'unknown',
    action_type: 'BLOCK_PORT',
    agent_id: agentId,
    src_ip: srcIp,
    dst_port: dstPort,
    // target stocke au format 'ip:port' pour rester compatible avec le schema
    // generique de la table pending_actions (colonne 'target' unique)
    target: `${srcIp}:${dstPort}`,
    rule_id: String(alert.rule?.id ?? 'unknown'),
    rule_level: Number(alert.rule?.level ?? 0),
    reason: 'high severity rule match on critical port',
    ar_block_command: `block-port${AR_BLOCK_TIMEOUT}`,
    ar_unblock_command: `unblock-port${AR_UNBLOCK_TIMEOUT}`
  }
};

