const row = $('Reconciliation Logic').item.json.pending_action;
const alertFullRaw = $('Reconciliation Logic').item.json.alert?.full_raw ?? {};
const agentId = alertFullRaw.alert?.agent?.id ?? alertFullRaw.agent?.id;

if (!agentId) {
  throw new Error('agent.id introuvable dans alert.full_raw - impossible de cibler l\'agent pour le rollback');
}

let command, args;
if (row.action_type === 'BLOCK_PORT') {
  const [ip, port] = String(row.target).split(':');
  command = 'unblock-port0';
  args = [ip, port];
} else {
  command = 'unblock-ip0';
  args = [row.target];
}

return {
  json: {
    agent_id: agentId,
    ar_command: command,
    ar_arguments: args,
    action_type: row.action_type,
    target: row.target,
    rule_id: row.rule_id ?? 'unknown',
    rule_level: Number(row.rule_level ?? 0),
    correlation_id: row.correlation_id
  }
};

